def planted():
    good = Value.tanh

    def bad(self):
        t = math.tanh(self.data)
        out = Value(t, (self,), "tanh")

        def _backward():
            self.grad += (1 - self.data ** 2) * out.grad
        out._backward = _backward
        return out
    Value.tanh = bad
    try:
        return check_gradients(MLP(2, [3, 1], seed=42), X4, Y4, 1e-6)
    finally:
        Value.tanh = good


def unchanged():
    m = MLP(2, [3, 1], seed=42)
    before = [p.data for p in m.parameters()]
    check_gradients(m, X4, Y4, 1e-6)
    return [p.data for p in m.parameters()] == before
